"""The lockfile check must pass matching pairs and catch every kind of drift."""

from __future__ import annotations

import importlib.util
from pathlib import Path

_SPEC = importlib.util.spec_from_file_location(
    "check_lockfiles", Path(__file__).resolve().parents[2] / "scripts" / "check_lockfiles.py"
)
assert _SPEC and _SPEC.loader
check_lockfiles = importlib.util.module_from_spec(_SPEC)
_SPEC.loader.exec_module(check_lockfiles)


def _lock(output: str, source: str, body: str, extra_flags: str = "") -> str:
    return (
        "#\n"
        "# This file is autogenerated by pip-compile with Python 3.11\n"
        "# by the following command:\n"
        "#\n"
        f"#    pip-compile --generate-hashes{extra_flags} --output-file={output} --strip-extras {source}\n"
        "#\n" + body
    )


def _pair(tmp_path: Path, source_text: str, lock_text: str) -> tuple[Path, Path]:
    source, lock = tmp_path / "requirements.in", tmp_path / "requirements.txt"
    source.write_text(source_text, encoding="utf-8")
    lock.write_text(lock_text, encoding="utf-8")
    return source, lock


LOCK_BODY = (
    "fastapi==0.136.3 \\\n    --hash=sha256:aaa\n    # via -r requirements.in\n"
    "psycopg==3.3.3 \\\n    --hash=sha256:bbb\n"
)


def test_matching_pair_passes(tmp_path):
    source, lock = _pair(
        tmp_path,
        "fastapi==0.136.3\npsycopg[binary]==3.3.3  # extras and comments are fine\n",
        _lock("requirements.txt", "requirements.in", LOCK_BODY),
    )
    assert check_lockfiles.problems_for(source, lock) == []


def test_a_bumped_input_without_a_relock_is_caught(tmp_path):
    source, lock = _pair(
        tmp_path,
        "fastapi==0.137.0\npsycopg[binary]==3.3.3\n",
        _lock("requirements.txt", "requirements.in", LOCK_BODY),
    )
    assert check_lockfiles.problems_for(source, lock) == [
        "requirements.in pins fastapi==0.137.0, but requirements.txt has fastapi==0.136.3"
    ]


def test_a_new_input_missing_from_the_lock_is_caught(tmp_path):
    source, lock = _pair(
        tmp_path,
        "fastapi==0.136.3\npsycopg==3.3.3\nredis==5.2.1\n",
        _lock("requirements.txt", "requirements.in", LOCK_BODY),
    )
    assert check_lockfiles.problems_for(source, lock) == [
        "requirements.in pins redis==5.2.1, but requirements.txt does not list redis"
    ]


def test_included_inputs_are_checked_too(tmp_path):
    (tmp_path / "base.in").write_text("fastapi==0.140.0\n", encoding="utf-8")
    source, lock = _pair(
        tmp_path,
        "-r base.in\npsycopg==3.3.3\n",
        _lock("requirements.txt", "requirements.in", LOCK_BODY),
    )
    assert check_lockfiles.problems_for(source, lock) == [
        "requirements.in pins fastapi==0.140.0, but requirements.txt has fastapi==0.136.3"
    ]


def test_a_header_for_another_file_is_caught(tmp_path):
    source, lock = _pair(
        tmp_path,
        "fastapi==0.136.3\n",
        _lock("requirements.lock", "requirements.txt", LOCK_BODY),
    )
    assert check_lockfiles.problems_for(source, lock) == [
        "requirements.txt: header does not compile requirements.in into requirements.txt"
    ]


def test_a_spurious_no_index_in_the_header_is_caught(tmp_path):
    source, lock = _pair(
        tmp_path,
        "fastapi==0.136.3\n",
        _lock("requirements.txt", "requirements.in", LOCK_BODY, extra_flags=" --no-index"),
    )
    assert check_lockfiles.problems_for(source, lock) == [
        "requirements.txt: header records --no-index; relock with the Click version the lock pins"
    ]


def test_the_repository_lockfiles_match_their_inputs():
    assert check_lockfiles.main() == 0
